import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Scalar-Variable-Basics.md","filePath":"manual-zh/CTABLES-Scalar-Variable-Basics.md","lastUpdated":1785684581000}'),h={name:"manual-zh/CTABLES-Scalar-Variable-Basics.md"};function n(o,t,i,s,c,l){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h4 id="_15-7-1-2-标量变量" tabindex="-1">15.7.1.2 标量变量 <a class="header-anchor" href="#_15-7-1-2-标量变量" aria-label="Permalink to &quot;15.7.1.2 标量变量&quot;">​</a></h4><p>对于分类变量，<code>CTABLES</code> 将表按每个类别划分为一个单元格。对于标度变量，<code>CTABLES</code> 则计算落入某个单元格的取值的汇总度量，默认是均值。例如，如果指定的唯一变量是标度变量，则输出为一个保存了所有数据均值的单元格：</p><pre><code>CTABLES /TABLE age.
</code></pre><table tabindex="0"><thead><tr><th></th><th>Mean</th></tr></thead><tbody><tr><td>D1. AGE: What is your age?</td><td>48</td></tr></tbody></table><p>标度变量可以与分类变量嵌套。以下示例展示了按性别和语言组的调查受访者平均年龄：</p><pre><code>CTABLES /TABLE gender &gt; age BY region.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>English</th><th>Spanish</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>Was this interview conducted in English or Spanish?</td><td></td></tr><tr><td></td><td></td><td></td><td>Mean</td><td>Mean</td></tr><tr><td>D1. AGE: What is your age?</td><td>S3a. GENDER:</td><td>Male</td><td>46</td><td>37</td></tr><tr><td>Female</td><td>51</td><td>39</td><td></td><td></td></tr></tbody></table><p>标度变量与分类变量的嵌套顺序会影响表的标签，但不影响表中显示的数据。以下示例展示了当标度变量与分类变量的嵌套顺序互换时输出的变化：</p><pre><code>CTABLES /TABLE age &gt; gender BY region.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>English</th><th>Spanish</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>Was this interview conducted in English or Spanish?</td><td></td></tr><tr><td></td><td></td><td></td><td>Mean</td><td>Mean</td></tr><tr><td>S3a. GENDER:</td><td>Male</td><td>D1. AGE: What is your age?</td><td>46</td><td>37</td></tr><tr><td>Female</td><td>D1. AGE: What is your age?</td><td>51</td><td>39</td><td></td></tr></tbody></table><p>每个节中只能出现一个标度变量；也就是说，标度变量不能直接或间接地嵌套在标度变量内部。标度变量只能出现在 <code>TABLE</code> 中的一个轴上。</p>`,11)])])}const S=d(h,[["render",n]]);export{E as __pageData,S as default};
